const dateFormat = new Intl.DateTimeFormat('en-US', {
  month: 'short',
  day: 'numeric',
  year: 'numeric',
  timeZone: 'UTC',
});

export const defaultNewsletterBooks: NewsletterBookshelfItem[] =
  DEFAULT_TITLES.map((title, index) => ({
    id: `edition-${DEFAULT_TITLES.length - index}`,
    title,
    date: dateFormat
      .format(new Date(Date.UTC(2026, 6, 31 - index * 7, 12)))
      .toUpperCase(),
    subtitle:
      'A concise collection of practical notes, experiments, and ideas for people building what comes next.',
  }));

export function hash(input: string): number {
  let value = 2166136261;
  for (let index = 0; index < input.length; index += 1) {
    value ^= input.charCodeAt(index);
    value = Math.imul(value, 16777619);
  }
  return value >>> 0;
}

export function seeded(seed: number): () => number {
  let value = seed >>> 0;
  return () => {
    // 0x6d2b79f5 (mulberry32 increment)
    value += 1831565813;
    let next = value;
    next = Math.imul(next ^ (next >>> 15), next | 1);
    next ^= next + Math.imul(next ^ (next >>> 7), next | 61);
    return ((next ^ (next >>> 14)) >>> 0) / 4294967296;
  };
}

function channel(value: number): number {
  const normalized = value / 255;
  return normalized <= 0.03928
    ? normalized / 12.92
    : ((normalized + 0.055) / 1.055) ** 2.4;
}

function luminance(hex: string): number {
  const color = Number.parseInt(hex.slice(1), 16);
  return (
    channel((color >> 16) & 255) * 0.2126 +
    channel((color >> 8) & 255) * 0.7152 +
    channel(color & 255) * 0.0722
  );
}

export function deriveLayout(items: NewsletterBookshelfItem[]): BookLayout[] {
  let cursor = 0;
  return items.map((item) => {
    const random = seeded(hash(item.id));
    const fallbackColor = PALETTE[Math.floor(random() * PALETTE.length)]!;
    const width = 0.34 + random() * 0.3;
    const bookHeight = 3.65 + (random() * 2 - 1) * 0.22;
    const color = item.color ?? fallbackColor;
    const foil = item.foil ?? (luminance(color) < 0.5 ? '#f2ead8' : '#3030ff');
    if (random() < 0.14) cursor += 0.2;
    const x = cursor + width / 2;
    cursor += width + 0.065;
    return {
      ...item,
      x,
      width,
      bookHeight,
      depth: bookHeight * 0.67,
      motif: Math.floor(random() * 8),
      color,
      foil,
    };
  });
}

export function nearestBook(books: BookLayout[], x: number): number {
  let nearest = 0;
  let distance = Number.POSITIVE_INFINITY;
  books.forEach((book, index) => {
    const next = Math.abs(book.x - x);
    if (next < distance) {
      nearest = index;
      distance = next;
    }
  });
  return nearest;
}

/** Horizontal camera range so the shelf ends stay roughly a third inset. */
export function shelfBounds(
  books: BookLayout[],
  stageWidth: number,
  stageHeight: number,
): ShelfBounds {
  const last = books.at(-1)?.x ?? 0;
  const aspect = stageWidth / Math.max(420, stageHeight);
  const visibleSpan = 2 * 10 * Math.tan((35 * Math.PI) / 360) * aspect;
  const inset = visibleSpan * 0.31;
  const min = Math.min(last / 2, (books[0]?.x ?? 0) + inset);
  const max = Math.max(last / 2, last - inset);
  return max <= min
    ? { min: last / 2, max: last / 2, visibleSpan }
    : { min, max, visibleSpan };
}

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function safeHref(
  href: string | undefined,
  base: string,
): string | null {
  if (!href) return null;
  try {
    const destination = new URL(href, base);
    if (destination.protocol !== 'http:' && destination.protocol !== 'https:') {
      return null;
    }
    return destination.href;
  } catch {
    return null;
  }
}

import * as THREE from 'three';
import { hash, seeded } from './bookshelf-layout';
import type { BookFace, BookLayout } from './types';

function drawMotif(
  context: CanvasRenderingContext2D,
  motif: number,
  x: number,
  y: number,
  size: number,
  color: string,
): void {
  context.save();
  context.translate(x + size / 2, y + size / 2);
  context.strokeStyle = color;
  context.fillStyle = color;
  context.lineWidth = Math.max(2, size * 0.035);

  if (motif === 0) {
    for (let index = -2; index <= 2; index += 1) {
      context.beginPath();
      context.arc(0, 0, size * (0.12 + index * 0.035), 0, Math.PI * 2);
      context.stroke();
    }
  } else if (motif === 1) {
    context.rotate(Math.PI / 4);
    for (let index = -1; index <= 1; index += 1) {
      context.strokeRect(
        -size * (0.24 + index * 0.055),
        -size * (0.24 + index * 0.055),
        size * (0.48 + index * 0.11),
        size * (0.48 + index * 0.11),
      );
    }
  } else if (motif === 2) {
    for (let index = 0; index < 6; index += 1) {
      context.rotate(Math.PI / 3);
      context.beginPath();
      context.roundRect(
        -size * 0.045,
        -size * 0.36,
        size * 0.09,
        size * 0.28,
        size * 0.04,
      );
      context.fill();
    }
    context.beginPath();
    context.arc(0, 0, size * 0.11, 0, Math.PI * 2);
    context.fill();
  } else if (motif === 3) {
    context.beginPath();
    for (let index = 0; index < 12; index += 1) {
      const radius = index % 2 ? size * 0.17 : size * 0.35;
      const angle = -Math.PI / 2 + (index * Math.PI) / 6;
      const px = Math.cos(angle) * radius;
      const py = Math.sin(angle) * radius;
      if (index === 0) context.moveTo(px, py);
      else context.lineTo(px, py);
    }
    context.closePath();
    context.stroke();
  } else if (motif === 4) {
    for (let row = -2; row <= 2; row += 1) {
      for (let column = -2; column <= 2; column += 1) {
        if ((row + column) % 2 === 0) {
          context.beginPath();
          context.arc(
            column * size * 0.13,
            row * size * 0.13,
            size * 0.035,
            0,
            Math.PI * 2,
          );
          context.fill();
        }
      }
    }
  } else if (motif === 5) {
    for (let index = -2; index <= 2; index += 1) {
      context.beginPath();
      context.moveTo(-size * 0.34, index * size * 0.12);
      context.bezierCurveTo(
        -size * 0.12,
        index * size * 0.12 - size * 0.11,
        size * 0.12,
        index * size * 0.12 + size * 0.11,
        size * 0.34,
        index * size * 0.12,
      );
      context.stroke();
    }
  } else if (motif === 6) {
    context.beginPath();
    context.moveTo(0, -size * 0.37);
    context.lineTo(size * 0.34, size * 0.28);
    context.lineTo(-size * 0.34, size * 0.28);
    context.closePath();
    context.stroke();
    context.beginPath();
    context.arc(0, size * 0.02, size * 0.11, 0, Math.PI * 2);
    context.fill();
  } else {
    context.rotate(Math.PI / 4);
    context.fillRect(-size * 0.035, -size * 0.36, size * 0.07, size * 0.72);
    context.fillRect(-size * 0.36, -size * 0.035, size * 0.72, size * 0.07);
    context.beginPath();
    context.arc(0, 0, size * 0.25, 0, Math.PI * 2);
    context.stroke();
  }
  context.restore();
}

function addNoise(
  context: CanvasRenderingContext2D,
  width: number,
  height: number,
  seed: number,
): void {
  const image = context.getImageData(0, 0, width, height);
  const random = seeded(seed);
  const data = image.data;
  for (let offset = 0; offset < data.length; offset += 4) {
    const noise = (random() - 0.5) * 5;
    data[offset] = data[offset]! + noise;
    data[offset + 1] = data[offset + 1]! + noise;
    data[offset + 2] = data[offset + 2]! + noise;
  }
  context.putImageData(image, 0, 0);
}

function drawClothWeave(
  context: CanvasRenderingContext2D,
  width: number,
  height: number,
  seed: number,
): void {
  const random = seeded(seed);
  context.save();
  context.lineCap = 'round';

  context.globalCompositeOperation = 'multiply';
  for (let x = 0.5; x < width; x += 3) {
    context.strokeStyle = `rgba(18, 16, 14, ${0.03 + random() * 0.035})`;
    context.lineWidth = 0.35 + random() * 0.3;
    context.beginPath();
    context.moveTo(x + (random() - 0.5) * 0.5, 0);
    context.lineTo(x + (random() - 0.5) * 0.5, height);
    context.stroke();
  }

  context.globalCompositeOperation = 'screen';
  for (let y = 0.5; y < height; y += 3) {
    context.strokeStyle = `rgba(255, 248, 232, ${0.035 + random() * 0.03})`;
    context.lineWidth = 0.3 + random() * 0.25;
    context.beginPath();
    context.moveTo(0, y + (random() - 0.5) * 0.5);
    context.lineTo(width, y + (random() - 0.5) * 0.5);
    context.stroke();
  }

  context.globalCompositeOperation = 'overlay';
  const fibres = Math.floor((width * height) / 850);
  for (let index = 0; index < fibres; index += 1) {
    const x = random() * width;
    const y = random() * height;
    const length = 3 + random() * 13;
    context.strokeStyle = `rgba(255, 255, 255, ${0.035 + random() * 0.055})`;
    context.lineWidth = 0.35 + random() * 0.4;
    context.beginPath();
    context.moveTo(x, y);
    context.lineTo(x + (random() - 0.5) * 2, y + length);
    context.stroke();
  }

  context.globalCompositeOperation = 'source-over';
  const edgeShade = context.createLinearGradient(0, 0, width, 0);
  edgeShade.addColorStop(0, 'rgba(0,0,0,.16)');
  edgeShade.addColorStop(0.045, 'rgba(0,0,0,.025)');
  edgeShade.addColorStop(0.5, 'rgba(255,255,255,.025)');
  edgeShade.addColorStop(0.955, 'rgba(0,0,0,.025)');
  edgeShade.addColorStop(1, 'rgba(0,0,0,.18)');
  context.fillStyle = edgeShade;
  context.fillRect(0, 0, width, height);
  context.restore();
}

function toTexture(canvas: HTMLCanvasElement): THREE.CanvasTexture {
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 8;
  texture.needsUpdate = true;
  return texture;
}

/** Page-block texture: ruled paper fibres with warm edge shading. */
export function paperTexture(book: BookLayout): THREE.CanvasTexture | null {
  const canvas = document.createElement('canvas');
  canvas.width = 192;
  canvas.height = 768;
  const context = canvas.getContext('2d', { willReadFrequently: true });
  if (!context) return null;
  const random = seeded(hash(`${book.id}-paper`));

  context.fillStyle = '#eee9dc';
  context.fillRect(0, 0, canvas.width, canvas.height);
  addNoise(
    context,
    canvas.width,
    canvas.height,
    hash(`${book.id}-paper-noise`),
  );

  for (let y = 0.5; y < canvas.height; y += 2) {
    const warm = Math.floor(116 + random() * 35);
    context.strokeStyle = `rgba(${warm}, ${warm - 6}, ${warm - 17}, ${0.09 + random() * 0.1})`;
    context.lineWidth = random() > 0.94 ? 1 : 0.42;
    context.beginPath();
    context.moveTo((random() - 0.5) * 4, y);
    context.bezierCurveTo(
      canvas.width * 0.33,
      y + (random() - 0.5) * 0.8,
      canvas.width * 0.66,
      y + (random() - 0.5) * 0.8,
      canvas.width + (random() - 0.5) * 4,
      y,
    );
    context.stroke();
  }

  for (let x = 0.5; x < canvas.width; x += 4) {
    context.strokeStyle = `rgba(124, 103, 72, ${0.025 + random() * 0.04})`;
    context.lineWidth = 0.35;
    context.beginPath();
    context.moveTo(x, 0);
    context.lineTo(x + (random() - 0.5) * 1.5, canvas.height);
    context.stroke();
  }

  for (let index = 0; index < 170; index += 1) {
    const x = random() * canvas.width;
    const y = random() * canvas.height;
    context.fillStyle = `rgba(112, 91, 59, ${0.025 + random() * 0.055})`;
    context.fillRect(x, y, 0.5 + random() * 1.2, 0.5 + random() * 2.5);
  }

  const edgeShade = context.createLinearGradient(0, 0, canvas.width, 0);
  edgeShade.addColorStop(0, 'rgba(96,72,42,.2)');
  edgeShade.addColorStop(0.08, 'rgba(138,112,72,.035)');
  edgeShade.addColorStop(0.5, 'rgba(255,255,255,.16)');
  edgeShade.addColorStop(0.92, 'rgba(138,112,72,.035)');
  edgeShade.addColorStop(1, 'rgba(96,72,42,.18)');
  context.fillStyle = edgeShade;
  context.fillRect(0, 0, canvas.width, canvas.height);

  return toTexture(canvas);
}

function wrapTitle(
  context: CanvasRenderingContext2D,
  title: string,
  maxWidth: number,
): string[] {
  const lines: string[] = [];
  let line = '';
  for (const word of title.split(/\s+/)) {
    const next = line ? `${line} ${word}` : word;
    if (context.measureText(next).width < maxWidth || !line) line = next;
    else {
      lines.push(line);
      line = word;
    }
  }
  if (line) lines.push(line);
  return lines;
}

/** Cloth-bound cover or spine with foil-stamped type and a seeded motif. */
export function coverTexture(
  book: BookLayout,
  brand: string,
  face: BookFace,
): THREE.CanvasTexture | null {
  const canvas = document.createElement('canvas');
  canvas.width = face === 'cover' ? 512 : 112;
  canvas.height = 768;
  const context = canvas.getContext('2d', { willReadFrequently: true });
  if (!context) return null;

  context.fillStyle = book.color;
  context.fillRect(0, 0, canvas.width, canvas.height);
  addNoise(
    context,
    canvas.width,
    canvas.height,
    hash(`${book.id}-${face}-noise`),
  );
  drawClothWeave(
    context,
    canvas.width,
    canvas.height,
    hash(`${book.id}-${face}-weave`),
  );
  context.fillStyle = book.foil;
  context.strokeStyle = book.foil;
  context.textBaseline = 'top';
  context.shadowColor = 'rgba(0, 0, 0, .3)';
  context.shadowBlur = 1.4;
  context.shadowOffsetX = 0.8;
  context.shadowOffsetY = 1.1;

  if (face === 'cover') {
    const margin = 58;
    context.font = '500 21px ui-monospace, SFMono-Regular, monospace';
    context.fillText(book.date, margin, 58);
    context.font = '700 54px Georgia, serif';
    const lines = wrapTitle(context, book.title, canvas.width - margin * 2);
    lines
      .slice(0, 5)
      .forEach((text, index) =>
        context.fillText(text, margin, 180 + index * 61),
      );
    context.fillRect(margin, 180 + Math.min(lines.length, 5) * 61 + 24, 92, 5);
    drawMotif(context, book.motif, 316, 510, 130, book.foil);
    context.font = '700 19px ui-monospace, SFMono-Regular, monospace';
    context.fillText(brand.toUpperCase(), margin, 690);
  } else {
    const gradient = context.createLinearGradient(0, 0, canvas.width, 0);
    gradient.addColorStop(0, 'rgba(0,0,0,.28)');
    gradient.addColorStop(0.18, 'rgba(0,0,0,0)');
    gradient.addColorStop(0.82, 'rgba(0,0,0,0)');
    gradient.addColorStop(1, 'rgba(0,0,0,.28)');
    context.fillStyle = gradient;
    context.fillRect(0, 0, canvas.width, canvas.height);
    context.fillStyle = book.foil;
    context.fillRect(22, 26, canvas.width - 44, 3);
    context.fillRect(22, 704, canvas.width - 44, 3);
    context.save();
    context.translate(canvas.width / 2, 58);
    context.rotate(Math.PI / 2);
    context.font = '700 37px Georgia, serif';
    const title =
      book.title.length > 36 ? `${book.title.slice(0, 34)}…` : book.title;
    context.fillText(title, 0, 13);
    context.restore();
    drawMotif(context, book.motif, 29, 625, 54, book.foil);
  }

  return toTexture(canvas);
}

export { default as NewsletterBookshelf } from './NewsletterBookshelf.vue';
export { defaultNewsletterBooks } from './bookshelf-layout';
export type {
  NewsletterBookshelfEmits,
  NewsletterBookshelfItem,
  NewsletterBookshelfProps,
} from './types';

import type { HTMLAttributes } from 'vue';

export interface NewsletterBookshelfItem {
  id: string;
  title: string;
  /** Printed on the cover and shown in the hover tooltip. */
  date: string;
  subtitle?: string;
  /** Opened when an already-focused book is activated again (http/https only). */
  href?: string;
  /** Cloth colour (hex). Falls back to a seeded palette pick. */
  color?: string;
  /** Foil/ink colour (hex). Falls back to cream on dark cloth, blue on light. */
  foil?: string;
}

export interface NewsletterBookshelfProps {
  items?: NewsletterBookshelfItem[];
  /** Stage height — number = px, string = any CSS length. */
  height?: number | string;
  /** Wordmark printed on every generated cover. */
  brand?: string;
  class?: HTMLAttributes['class'];
}

export interface NewsletterBookshelfEmits {
  select: [item: NewsletterBookshelfItem, index: number];
}

export interface BookLayout extends NewsletterBookshelfItem {
  x: number;
  width: number;
  bookHeight: number;
  depth: number;
  motif: number;
  color: string;
  foil: string;
}

export type BookFace = 'cover' | 'spine';

/** Mutable camera/orbit targets shared between the Vue shell and the engine. */
export interface ShelfRig {
  cameraX: number;
  yaw: number;
  pitch: number;
}

export interface ShelfBounds {
  min: number;
  max: number;
  visibleSpan: number;
}

export interface ShelfViewState {
  hoveredIndex: number | null;
  selectedIndex: number | null;
  reducedMotion: boolean;
}

/** Snapshot a book flies from when it enters or leaves the focused view. */
export interface BookFlight {
  startedAt: number;
  x: number;
  y: number;
  z: number;
  rotationX: number;
  rotationY: number;
  rotationZ: number;
  scale: number;
}

export type ShelfGestureMode = 'pending' | 'drag' | 'orbit';

export interface ShelfGesture {
  mode: ShelfGestureMode;
  x: number;
  y: number;
  startX: number;
  startY: number;
  downIndex: number | null;
}

export interface BookshelfEngine {
  setBooks: (books: BookLayout[], brand: string) => void;
  setView: (view: ShelfViewState) => void;
  /** Advance one frame (seconds since the previous frame) and render. */
  frame: (delta: number) => void;
  resize: (width: number, height: number) => void;
  /** Index of the book under the given client point, or null. */
  pick: (clientX: number, clientY: number) => number | null;
  dispose: () => void;
}
